def fmt_currency(val):
    if val >= 1e6:
        return f'${val/1e6:.2f}M'
    elif val >= 1e3:
        return f'${val:,.0f}'
    else:
        return f'${val:,.2f}'

def fmt_pct(val):
    return f'{val:.2%}'

def fmt_num(val):
